    @staticmethod
    def _free_port():
        sock = socket.socket()
        sock.bind(('127.0.0.1', 0))
        port = sock.getsockname()[1]
        sock.close()
        return port

    def _start_owned(self):
        handle, name = tempfile.mkstemp(prefix='chronicleflow-acceptance-', suffix='.log')
        os.close(handle)
        self.log_path = Path(name)
        db_dir = Path(tempfile.mkdtemp(prefix='chronicleflow-acceptance-db-'))
        env = dict(os.environ)
        existing = env.get('PYTHONPATH')
        env['PYTHONPATH'] = str(SRC_DIR) + ((os.pathsep + existing) if existing else '')
        log = open(self.log_path, 'a')
        self.owned = subprocess.Popen(
            [
                sys.executable,
                '-m',
                'chronicleflow.server',
                '--host',
                '127.0.0.1',
                '--port',
                str(self.port),
                '--database',
                str(db_dir / 'acceptance.db'),
            ],
            cwd=str(CLONE_ROOT),
            env=env,
            stdout=log,
            stderr=subprocess.STDOUT,
        )
        self._wait_ready()

    def _wait_ready(self):
        deadline = time.time() + 30
        last = 'no attempt made'
        while time.time() < deadline:
            try:
                status, raw, _ = self.request('GET', '/health')
                if status == 200:
                    return
                last = 'health returned {} {!r}'.format(status, raw[:120])
            except OSError as exc:
                last = 'connection failed: {}'.format(exc)
            time.sleep(0.1)
        tail = ''
        if self.log_path is not None and self.log_path.exists():
            tail = self.log_path.read_text(errors='replace')[-1500:]
        raise RuntimeError(
            'service on port {} did not become ready ({}); log tail: {}'.format(self.port, last, tail)
        )

    def request(self, method, path, body=None, raw=None, key=None, tenant=None):
        headers = {}
        payload = None
        if raw is not None:
            payload = raw if isinstance(raw, bytes) else raw.encode('utf-8')
            headers['Content-Type'] = 'application/json'
        elif body is not None:
            payload = json.dumps(body, separators=(',', ':')).encode('utf-8')
            headers['Content-Type'] = 'application/json'
        if key is not None:
            headers['Idempotency-Key'] = key
        if tenant is not None:
            headers['X-Tenant-Id'] = tenant
        connection = http.client.HTTPConnection('127.0.0.1', self.port, timeout=30)
        try:
            connection.request(method, path, payload, headers)
            response = connection.getresponse()
            raw_out = response.read()
            status = response.status
        finally:
            connection.close()
        parsed = None
        try:
            parsed = json.loads(raw_out.decode('utf-8'))
        except Exception:
            parsed = None
        return status, raw_out, parsed

    def close(self):
        if self.owned is not None:
            self.owned.terminate()
            try:
                self.owned.wait(timeout=10)
            except Exception:
                self.owned.kill()


def discover_entry(service):
    probe_run = 'entry-probe'
    path_route = '/executions/{}/maps/probe-map/instances/0/delete'.format(probe_run)
    body_route = '/executions/{}/instances/delete'.format(probe_run)
    status_path, raw_path, _ = service.request('POST', path_route, body={'probe': 1}, key=next_key('probe'))
    status_body, raw_body, _ = service.request('POST', body_route, body={'probe': 1}, key=next_key('probe'))
    path_ok = status_path == 400
    body_ok = status_body == 400
    if path_ok == body_ok:
        raise AssertionError(
            'cannot determine the instance operation entry: {} -> {} {!r}; {} -> {} {!r}'.format(
                path_route, status_path, raw_path[:120], body_route, status_body, raw_body[:120]
            )
        )
    style = 'body' if body_ok else 'path'
    print('instance operation entry discovered:', style)
    return Entry(style, service)


class Entry:
    def __init__(self, style, service):
        self.style = style
        self.service = service
        self.last_path = ''
        self.last_body = ''

    def _path_route(self, run, map_id, index, action):
        return '/executions/{}/maps/{}/instances/{}/{}'.format(run, map_id, index, action)

    def _body_route(self, run, action):
        return '/executions/{}/instances/{}'.format(run, action)

    def _target(self, map_id, index, loop):
        body = {'map_id': map_id, 'index': index}
        if loop is not None:
            body['loop_id'] = loop[0]
            body['iteration'] = loop[1]
        return body

    def delete(self, run, map_id, index, loop=None, key=None, tenant=None):
        if self.style == 'path':
            path = self._path_route(run, map_id, index, 'delete')
            body = {}
        else:
            path = self._body_route(run, 'delete')
            body = self._target(map_id, index, loop)
        self.last_path = path
        self.last_body = json.dumps(body, separators=(',', ':'))
        return self.service.request('POST', path, body=body, key=key, tenant=tenant)

    def modify(self, run, map_id, index, value, loop=None, key=None, tenant=None):
        if self.style == 'path':
            path = self._path_route(run, map_id, index, 'modify')
            body = {'input': value}
        else:
            path = self._body_route(run, 'modify')
            body = self._target(map_id, index, loop)
            body['input'] = value
        self.last_path = path
        self.last_body = json.dumps(body, separators=(',', ':'))
        return self.service.request('POST', path, body=body, key=key, tenant=tenant)

    def delete_unknown_field(self, run, map_id, index, key=None):
        if self.style == 'path':
            return self.service.request(
                'POST', self._path_route(run, map_id, index, 'delete'), body={'unexpected': 1}, key=key
            )
        body = self._target(map_id, index, None)
        body['unexpected'] = 1
        return self.service.request('POST', self._body_route(run, 'delete'), body=body, key=key)

    def delete_non_object_body(self, run, map_id, index, key=None):
        if self.style == 'path':
            return self.service.request(
                'POST', self._path_route(run, map_id, index, 'delete'), raw=b'[]', key=key
            )
        return self.service.request('POST', self._body_route(run, 'delete'), raw=b'[]', key=key)

    def delete_bad_index(self, run, map_id, index_text, key=None):
        if self.style == 'path':
            return self.service.request(
                'POST', self._path_route(run, map_id, index_text, 'delete'), body={}, key=key
            )
        return self.service.request(
            'POST', self._body_route(run, 'delete'), body={'map_id': map_id, 'index': index_text}, key=key
        )

    def modify_missing_input(self, run, map_id, index, key=None):
        if self.style == 'path':
            return self.service.request(
                'POST', self._path_route(run, map_id, index, 'modify'), body={}, key=key
            )
        return self.service.request(
            'POST', self._body_route(run, 'modify'), body=self._target(map_id, index, None), key=key
        )

    def modify_unknown_field(self, run, map_id, index, value, key=None):
        if self.style == 'path':
            return self.service.request(
                'POST',
                self._path_route(run, map_id, index, 'modify'),
                body={'input': value, 'unexpected': 1},
                key=key,
            )
        body = self._target(map_id, index, None)
        body['input'] = value
        body['unexpected'] = 1
        return self.service.request('POST', self._body_route(run, 'modify'), body=body, key=key)

    def modify_non_object_body(self, run, map_id, index, key=None):
        if self.style == 'path':
            return self.service.request(
                'POST', self._path_route(run, map_id, index, 'modify'), raw=b'[]', key=key
            )
        return self.service.request('POST', self._body_route(run, 'modify'), raw=b'[]', key=key)

    def modify_non_finite(self, run, map_id, index, literal, key=None):
        if self.style == 'path':
            text = '{"input":{"v":' + literal + '}}'
            return self.service.request(
                'POST', self._path_route(run, map_id, index, 'modify'), raw=text, key=key
            )
        text = (
            '{"map_id":'
            + json.dumps(map_id)
            + ',"index":'
            + json.dumps(index)
            + ',"input":{"v":'
            + literal
            + '}}'
        )
        return self.service.request('POST', self._body_route(run, 'modify'), raw=text, key=key)

    def modify_bad_index(self, run, map_id, index_text, value, key=None):
        if self.style == 'path':
            return self.service.request(
                'POST',
                self._path_route(run, map_id, index_text, 'modify'),
                body={'input': value},
                key=key,
            )
        return self.service.request(
            'POST',
            self._body_route(run, 'modify'),
            body={'map_id': map_id, 'index': index_text, 'input': value},
            key=key,
        )


def workflow_doc(wf_id, template=None, max_instances=10):
    return {
        'id': wf_id,
        'nodes': [
            {'id': 'collect', 'kind': 'task', 'depends_on': []},
            {
                'id': 'fanout',
                'kind': 'map',
                'depends_on': ['collect'],
                'source': 'collect',
                'path': 'items',
                'max_instances': max_instances,
                'template': {'id': 'work'} if template is None else template,
            },
        ],
    }


def nested_workflow_doc(wf_id):
    return {
        'id': wf_id,
        'nodes': [
            {'id': 'entry', 'kind': 'task', 'depends_on': []},
            {
                'id': 'fanout',
                'kind': 'map',
