    }


def create_workflow(service, doc, key, tenant=None):
    status, raw, parsed = service.request('POST', '/workflows', body=doc, key=key, tenant=tenant)
    check(status == 201, 'POST /workflows accepted workflow {} ({})'.format(doc['id'], status))
    return parsed


def create_execution(service, run, wf_id, key, input_value=None, tenant=None):
    body = {'id': run, 'workflow_id': wf_id, 'input': {} if input_value is None else input_value}
    status, raw, parsed = service.request('POST', '/executions', body=body, key=key, tenant=tenant)
    check(status == 201, 'POST /executions started {} ({})'.format(run, status))
    return parsed


def advance(service, run, body, key, tenant=None):
    return service.request('POST', '/executions/{}/advance'.format(run), body=body, key=key, tenant=tenant)


def expand(service, run, items, key, tenant=None):
    status, raw, parsed = advance(service, run, {'output': {'items': list(items)}}, key, tenant)
    check(status == 200, 'advancing the source task expanded the map ({})'.format(status))
    return parsed


def get_state(service, run, tenant=None):
    status, raw, parsed = service.request('GET', '/executions/{}'.format(run), tenant=tenant)
    check(status == 200, 'GET /executions/{} returned 200'.format(run))
    return status, raw, parsed


def get_events(service, run, tenant=None):
    status, raw, parsed = service.request('GET', '/executions/{}/events'.format(run), tenant=tenant)
    check(status == 200, 'GET /executions/{}/events returned 200'.format(run))
    return parsed['events']


def replay_check(service, run, tenant=None):
    status, raw, parsed = service.request('POST', '/executions/{}/replay'.format(run), tenant=tenant)
    check(status == 200, 'POST /executions/{}/replay returned 200'.format(run))
    check(parsed.get('consistent') is True, 'replay reports consistent true')
    _, _, state = get_state(service, run, tenant=tenant)
    check(
        parsed.get('execution') == state,
        'the state rebuilt from the event stream equals the materialized state',
    )


def scenario_delete_keeps_order(service, entry):
    create_workflow(service, workflow_doc('core-wf-1'), next_key('core-wf'))
